+static int
+dissect_iperf3_tcp(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
+{
+    tcp_conversation_data *conversation;
+    conversation = conversation_get_proto_data(GET_TCP_CONV(pinfo), proto_iperf3);
+    if (!conversation)
+        conversation = tcp_set_conversation_data(pinfo);
+
+    uint32_t nbytes = tvb_reported_length(tvb);
+    proto_item *ti  = proto_tree_add_item(tree, proto_iperf3, tvb, 0, -1, ENC_NA);
+    proto_tree *iperf3_tree = proto_item_add_subtree(ti, ett_iperf3);
+
+    if (pinfo->num == conversation->first_frame && nbytes == COOKIE_SIZE) {
+        const guint8 *msg;
+        proto_tree_add_item_ret_string(iperf3_tree, hf_iperf3_cookie, tvb, 0, 37,
+                                                    ENC_ASCII,pinfo->pool, &msg);
+        col_info_preface_TCP(pinfo);
+        col_append_fstr(pinfo->cinfo, COL_INFO, "cookie: \"%s\"", msg);
+        return nbytes;
+    }
+
+    bool is_actually_control = FALSE;
+    if (conversation->could_be_control)
+        is_actually_control = attempt_dissect_as_control(tvb, pinfo, tree, nbytes, conversation, iperf3_tree);
+
+    if ( ! is_actually_control ) { /* dissect as payload */
+        col_set_str(pinfo->cinfo, COL_PROTOCOL, "iPerf3");
+        call_data_dissector(tvb, pinfo, tree); // deals with payload size = 0
+    }
+    return nbytes;
+}
+
+static bool
+attempt_dissect_as_control(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree,
+    uint32_t nbytes, tcp_conversation_data *conversation, proto_tree *iperf3_tree) {
+
+
+    if (nbytes == 1) {
+        int8_t state_code = tvb_get_gint8(tvb, 0);
+        if (state_code < -2 || state_code > 16) goto bad;
+
+        const gchar *msg = val_to_str(state_code, iperf3_state_type, "Unknown %d");
+        col_info_preface_TCP(pinfo);
+        col_append_fstr(pinfo->cinfo, COL_INFO, "%s(%"PRIi8")", msg, state_code);
+        proto_tree_add_item(iperf3_tree, hf_iperf3_state, tvb, 0, 1, ENC_BIG_ENDIAN);
+        return TRUE;
+
+    } else if (nbytes == 4) {
+
+        uint64_t json_size = tvb_get_guint32(tvb, 0, ENC_BIG_ENDIAN);
+        col_info_preface_TCP(pinfo);
+        col_append_fstr(pinfo->cinfo, COL_INFO,
+            "Next message is JSON of this length: %" PRIu64 "", json_size);
+        proto_tree_add_item(iperf3_tree, hf_iperf3_prejson, tvb, 0, 4, ENC_BIG_ENDIAN);
+        return TRUE;
+
+    } else if (tvb_get_guint16(tvb, 0, ENC_BIG_ENDIAN) == 0x7b22 ) {
+        /* first bytes are {" */
+
+        /* if the last byte isn't } then our JSON has been segmented.
+            not theoretically perfect since not every } character
+            ends the JSON... maybe we track the previous length */
+        if (tvb_get_guint8(tvb, (gint) nbytes - 1) == 0x7d) {
+            guint8 *buffer = tvb_get_string_enc(pinfo->pool, tvb, 0, (gint) nbytes, ENC_UTF_8);
+            col_info_preface_TCP(pinfo);
+            col_append_fstr(pinfo->cinfo, COL_INFO, "%s", buffer);
+            col_set_fence(pinfo->cinfo, COL_PROTOCOL);
+            call_dissector(json_handle, tvb, pinfo, tree);
+            return TRUE;
+
+        } else {
+            pinfo->desegment_offset = 0;
+            pinfo->desegment_len = DESEGMENT_ONE_MORE_SEGMENT;
+            return FALSE;
+        }
+
+    } else {
+        bad:
+        conversation->could_be_control=FALSE;
+        /* if you ever fail to match the data the packet couldn't have been part of the control connection */
+        return FALSE;
+    }
+}
+
+static tcp_conversation_data *
+tcp_set_conversation_data(packet_info *pinfo)
+{
+    tcp_conversation_data *conversation;
+    conversation = wmem_new0(wmem_file_scope(), tcp_conversation_data);
+    *conversation = (tcp_conversation_data) {.could_be_control = TRUE, .first_frame = pinfo->num };
+    conversation_add_proto_data(GET_TCP_CONV(pinfo), proto_iperf3, conversation);
+    return conversation;
+}
